      '一起釐清三題：這件事整體的願景是什麼、好的結果長什麼樣；達成它需要哪些不同的工作片段；哪些片段需要人的專業、創意或判斷。',
      '注意課文的提醒——要真的對話，不是各自丟一段話就結束。',
