      '做「Bad Prompt Makeover」練習（約 10 分鐘）：請 Claude 出幾個寫得很爛的提示給你改。',
      '逐題改寫，同時補上明確的產品描述、過程引導與表現規格。',
      '把改寫前後版本拿給 Claude 討論，請它回饋「這樣改為什麼能讓它給出更好的回應」。',
      '約 5 分鐘後角色互換，改由你出爛提示讓 Claude 來修。',
