      '直接用白話下任務，看思考過程確認它用了對的 Skill。',
      '要自建就開新對話講你想做什麼，回答追問、上傳素材、儲存。',
      '挑一項重複流程，寫下觸發條件、四個步驟、必要輸入和完成標準。'
