      ['寫好研究提示', '講清楚目標、指定章節結構、加上限制條件。最實用的一招：先請 Claude 幫你把提示改好再開跑。'],
      ['引用是入口不是保證', '引用證明的是「這句話出自這裡」，不是「這件事是對的」。重要結論還是要打開來源看。']
